const docId="REDACTED";
const r=await tools.mcp__codex_apps__google_drive_get_document_text({document_id:docId});
const d=r.structuredContent;
const originalPrefix="Ursprünglich beanstandet: ";
const currentPrefix="Aktuelle Fassung: ";
const cases=[]; let current=null;
for(const p of d.paragraphs){
  const s=p.text.trim();
  if(/^(P\d{2}|DAT-\d{2}|AGB-\d{2})$/.test(s)){
    if(current) cases.push(current); current={id:s}; continue;
  }
  if(!current) continue;
  if(s.startsWith("Tenor: ")) current.tenor=s.slice("Tenor: ".length);
  else if(s.startsWith(originalPrefix)) current.urspruenglich_beanstandet=s.slice(originalPrefix.length);
  else if(s.startsWith(currentPrefix)) current.aktuelle_fassung=s.slice(currentPrefix.length);
  else if(s.startsWith("Statistik: ")){
    const m=s.match(/×\s*(\d+)\s*%\s*·\s*✓\s*(\d+)\s*%\s*·\s*↗\s*(\d+)\s*%\s*—\s*(\d+)\s*Stimmen/);
    if(!m) throw new Error(`Statistik nicht erkannt: ${s}`);
    const dist={verstoss_besteht_fort:+m[1],verstoss_beseitigt:+m[2],anderer_sachverhalt:+m[3]};
    const entries=Object.entries(dist), max=Math.max(...entries.map(x=>x[1]));
    const plurality=entries.filter(x=>x[1]===max).map(x=>x[0]);
    current.stimmen={anzahl:+m[4],verteilung_pct:dist,pluralitaetsklasse:plurality.length===1?plurality[0]:null,mehrheitsklasse:max>50&&plurality.length===1?plurality[0]:null};
  }
}
if(current) cases.push(current);
